import{_ as t,o as i,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-10-30","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-10-30","date":"2024-10-30T00:00:00.000Z","updated":"2024-10-30T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","多站点复制","通知同步"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-30.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-30.md","lastUpdated":1780459816000}'),n={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-30.md"};function r(s,l,g,p,a,_){return i(),e("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph RGW 功能讨论及多站点复制优化</p><p><strong>参会人员</strong>: 开发团队成员</p><p><strong>主要议题</strong>:</p><ol><li><p><strong>V2 通知同步问题</strong></p><ul><li><strong>问题背景</strong>: Squid 中引入通知同步功能后，由于不同区域使用不同的消息代理，导致通知同步出现问题。</li><li><strong>讨论内容</strong>: <ul><li>是否禁用 V2 通知同步功能，恢复到之前的配置方式。</li><li>提出在主题配置中添加一个标志，用于控制是否同步主题的建议。</li><li>讨论在通知级别添加过滤器的可行性，以避免同步问题。</li></ul></li><li><strong>决定事项</strong>: <ul><li>在 PR（Pull Request，代码审查请求）讨论中进一步细化过滤器方案，并评估其可行性。</li></ul></li></ul></li><li><p><strong>多站点复制优化</strong></p><ul><li><strong>问题背景</strong>: 当前 Ceph 的多站点复制功能在处理大规模数据时存在效率问题，尤其是在跨区域复制时。</li><li><strong>讨论内容</strong>: <ul><li>讨论如何在多站点复制中优化日志记录和数据同步，减少不必要的日志操作。</li><li>提出通过同步策略（sync policies）来控制跨区域复制的建议。</li><li>讨论在全量同步和增量同步中应用过滤器，以减少不必要的同步操作。</li></ul></li><li><strong>决定事项</strong>: <ul><li>在 PR 中进一步讨论和优化多站点复制的实现，特别是如何处理全量同步和增量同步的过滤问题。</li></ul></li></ul></li></ol><p><strong>后续行动计划</strong>:</p><ol><li><p><strong>V2 通知同步问题</strong>:</p><ul><li>在 PR 中进一步讨论过滤器方案，并评估其可行性。</li><li>开发团队将根据讨论结果进行代码调整。</li></ul></li><li><p><strong>多站点复制优化</strong>:</p><ul><li>在 PR 中继续讨论多站点复制的优化方案，特别是如何处理全量同步和增量同步的过滤问题。</li><li>开发团队将进行代码审查，并在测试环境中验证多站点复制的性能和稳定性。</li></ul></li></ol><p><strong>下次会议</strong>:</p><ul><li>将继续讨论多站点复制的优化问题，并解决相关技术细节。</li></ul><p><strong>备注</strong>:</p><ul><li>会议中提到的技术细节和代码实现将在 PR 中进一步讨论和确认。</li></ul>',11)])])}const d=t(n,[["render",r]]);export{c as __pageData,d as default};
